// median-tests | median / sorting-and-assertions | single / p3

import { test } from "node:test";
import assert from "node:assert/strict";

function median(values: readonly number[]): number {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 1
    ? sorted[middle]
    : (sorted[middle - 1] + sorted[middle]) / 2;
}

test("median handles odd input", () => {
  assert.equal(median([11]), 11);
});

test("median handles empty input", () => {
  assert.equal(median([]), 0);
});

test("median keeps duplicate values", () => {
  assert.equal(median([12, 12, 11, 11]), 11.5);
});

