// linked-list | push-and-sum / pointer-traversal | large / p2

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *push_front(Node *head, int value) {
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        return NULL;
    }
    node->value = value;
    node->next = head;
    return node;
}

static long list_sum(const Node *head) {
    long total = 0;
    for (const Node *node = head; node != NULL; node = node->next) {
        total += node->value;
    }
    return total;
}

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    Node *head = NULL;
    head = push_front(head, 1000);
    head = push_front(head, 1003);
    head = push_front(head, 1006);
    head = push_front(head, 1009);
    head = push_front(head, 1012);
    printf("sum=%ld\n", list_sum(head));
    free_list(head);
    return EXIT_SUCCESS;
}

