// group-sales | group-by-region / hash-map | large / p1

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public final class Demo {
    public record Sale(int id, String region, long amount) {}

    static List<Map.Entry<String, Long>> groupByRegion(List<Sale> sales) {
        Map<String, Long> totals = new HashMap<>();
        for (Sale sale : sales) {
            totals.merge(sale.region(), sale.amount(), Long::sum);
        }
        List<Map.Entry<String, Long>> entries = new ArrayList<>(totals.entrySet());
        entries.sort(Map.Entry.<String, Long>comparingByValue(Comparator.reverseOrder()));
        return entries;
    }

    public static void main(String[] args) {
        List<Sale> sales = List.of(
        new Sale(1, "north", 1000),
        new Sale(2, "south", 1006),
        new Sale(3, "east", 1012),
        new Sale(4, "west", 1018),
        new Sale(5, "north", 1024),
        new Sale(6, "south", 1030),
        new Sale(7, "east", 1036),
        new Sale(8, "west", 1042),
        new Sale(9, "north", 1048),
        new Sale(10, "south", 1054),
        new Sale(11, "east", 1060),
        new Sale(12, "west", 1066)
        );
        for (Map.Entry<String, Long> entry : groupByRegion(sales)) {
            System.out.printf("%s=%d%n", entry.getKey(), entry.getValue());
        }
    }
}

