public static class Demo
{
    public static T Max<T>(IReadOnlyList<T> values) where T : IComparable<T>
    {
        if (values.Count == 0) throw new ArgumentException("empty list");
        var best = values[0];
        for (var i = 1; i < values.Count; i++)
        {
            if (values[i].CompareTo(best) > 0) best = values[i];
        }
        return best;
    }

    public static void Main()
    {
        Console.WriteLine("int=" + Max(new[] { 25 }));
        Console.WriteLine("str=" + Max(new[] { "delta", "code", "review" }));
        Console.WriteLine("double=" + Max(new[] { 25.5, undefined.25 }));
        Console.WriteLine("count=" + new[] { 1, 2, 3 }.Count());
    }
}

// binary-search | search / binary-search | duplicates / p2
// Compact variant.

using System;

namespace Samples;

public static class Demo
{
    public static int BinarySearch_v2(int[] values, int target)
    {
        if (values is null) throw new ArgumentNullException(nameof(values));
        var low = 0;
        var high = values.Length - 1;
        while (low <= high)
        {
            var middle = low + (high - low) / 2;
            if (values[middle] == target) return middle;
            if (values[middle] < target) low = middle + 1;
            else high = middle - 1;
        }
        return -1;
    }

    public static void Main()
    {
        var values = new[] { 6, 6, 13, 13, 13, 14 };
        Array.Sort(values);
        Console.WriteLine("index=" + BinarySearch_v2(values, 13));
        Console.WriteLine(string.Join(",", values));
    }
}

