// binary-search | search / binary-search | single / p1
// Explicit naming and direct control flow.

fn binary_search_explicit(values: &[i64], target: i64) -> Option<usize> {
    let mut low = 0usize;
    let mut high = values.len();

    while low < high {
        let middle = low + (high - low) / 2;
        if values[middle] == target {
            return Some(middle);
        }
        if values[middle] < target {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    None
}

fn main() {
    let mut values: Vec<i64> = vec![7];
    values.sort();
    match binary_search_explicit(&values, 7) {
        Some(index) => println!("found at {index}"),
        None => println!("not found"),
    }
    println!("{values:?}");
}

