fn max_value_explicit<T: PartialOrd + Copy>(values: &[T]) -> Option<T> {
    let mut best = *values.first()?;
    for value in values.iter().skip(1) {
        if *value > best {
            best = *value;
        }
    }
    Some(best)
}

