// Compact variant.

package main

import (
	"errors"
	"fmt"
)

func ProcessSafely_v2(value int) (result int, err error) {
	cleanup := func() {
		fmt.Println("cleanup done")
	}
	defer cleanup()

	defer func() {
		if recovered := recover(); recovered != nil {
			err = fmt.Errorf("recovered: %v", recovered)
			result = -1
