// worker-pool | parallel-transform / goroutine-channel | duplicates / p2
// Defensive variant with descriptive identifiers.

package main

import (
	"fmt"
	"sync"
)

func transform(value int) int {
	return value*2 + 10
}

func RunPool_safe(values []int, workers int) []int {
	jobs := make(chan int, len(values))
	results := make(chan int, len(values))

	var group sync.WaitGroup
	for worker := 0; worker < workers; worker++ {
		group.Add(1)
		go func() {
			defer group.Done()
			for value := range jobs {
				results <- transform(value)
			}
		}()
	}

	go func() {
		defer close(jobs)
		for _, value := range values {
			jobs <- value
		}
	}()

	go func() {
		group.Wait()
		defer close(results)
	}()

	output := make([]int, 0, len(values))
	for value := range results {
		output = append(output, value)
	}
	return output
}

func main() {
	values := []int{13, 13, 6, 13, 6, 14}
	fmt.Println(RunPool_safe(values, 5))
}

