package main

import (
	"fmt"
	"sort"
)

func BinarySearch_doc(values []int, target int) int {
	low := 0
	high := len(values) - 1
	for low <= high {
		middle := low + (high-low)/2
		switch {
		case values[middle] == target:
			return middle
		case values[middle] < target:
			low = middle + 1
		default:
			high = middle - 1
		}
	}
	return -1
}

func main() {
	values := []int{7}
	sort.Ints(values)
	index := BinarySearch_doc(values, 7)
	fmt.Printf("index=%d values=%v\n", index, values)
}

