)

func Divide_v2(numerator, denominator int) (int, error) {
	if denominator == 0 {
		return 0, ErrDivideByZero
	}
	result := numerator / denominator
	if result > 1006 || result < -1006 {
		return 0, fmt.Errorf("%w: %d", ErrOutOfRange, result)
	}
	return result, nil
}

